import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        String s = r.next();
        int n = s.length();
        int[] first = new int[26], last = new int[26];
        Arrays.fill(first, -1);
        for (int i = 0; i < n; i++) { int c = s.charAt(i) - 'a'; if (first[c] < 0) first[c] = i; last[c] = i; }
        int ans = 0;
        for (int ch = 0; ch < 26; ch++) {
            int start = first[ch];
            if (start < 0) continue;
            int end = start;
            for (int i = start; i < n; i++) {
                int c = s.charAt(i) - 'a';
                if (first[c] < start) break;
                end = Math.max(end, last[c]);
                if (i == end && i - start + 1 < n) ans = Math.max(ans, i - start + 1);
            }
        }
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	s := readToken()
	n := len(s)
	var first, last [26]int
	for i := range first {
		first[i] = -1
	}
	for i := 0; i < n; i++ {
		c := s[i] - 'a'
		if first[c] < 0 {
			first[c] = i
		}
		last[c] = i
	}
	ans := 0
	for ch := 0; ch < 26; ch++ {
		start := first[ch]
		if start < 0 {
			continue
		}
		end := start
		for i := start; i < n; i++ {
			c := s[i] - 'a'
			if first[c] < start {
				break
			}
			end = max(end, last[c])
			if i == end && i-start+1 < n {
				ans = max(ans, i-start+1)
			}
		}
	}
	fmt.Println(ans)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
